import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.DhF4LrUq.js";const o="/shipperdog/snapshot/screenshots/roles/console-tenant-dashboard.png",g=JSON.parse('{"title":"Tenant Admin quickstart","description":"Quickstart for Tenant Admins — tenant members, portal testers, version grants, the device fleet, and the tenant dashboard, all scoped to your tenant.","frontmatter":{"description":"Quickstart for Tenant Admins — tenant members, portal testers, version grants, the device fleet, and the tenant dashboard, all scoped to your tenant."},"headers":[],"relativePath":"roles/tenant-admin.md","filePath":"roles/tenant-admin.md"}'),r={name:"roles/tenant-admin.md"};function i(h,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="tenant-admin-quickstart" tabindex="-1">Tenant Admin quickstart <a class="header-anchor" href="#tenant-admin-quickstart" aria-label="Permalink to &quot;Tenant Admin quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You administer <strong>one tenant</strong> — the customer or business entity your organization created for your teams. Your system role is <strong><code>TENANT_ADMIN</code></strong>, held on your membership in that tenant, and everything you can do is scoped to it: you will never see another tenant&#39;s data, and other tenants&#39; administrators will never see yours. Your daily work is the tenant&#39;s people (members and portal testers), what those testers can install (version grants), the device fleet they install from, and the tenant dashboard that watches it all. If you also hold organization-scope roles, work one track per session — the <a href="/shipperdog/snapshot/roles/">other role guides</a> cover the rest. The organization above you is administered by the <a href="/shipperdog/snapshot/roles/org-admin">Organization Admin</a> track — tenant settings like the tenant&#39;s own name are theirs, not yours.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Manage tenant members</strong> — add console colleagues to your tenant, change their roles, suspend and reactivate them. Suspension cuts access on the next request; reactivation restores it without re-inviting.</li><li><strong>Manage portal testers</strong> — link tester records to your tenant (that link is what makes the Tester Portal serve them), suspend a noisy one, or remove them. Removal keeps the history and can be re-linked later.</li><li><strong>Control what testers can install</strong> — version grants, in four shapes: exactly one version, the whole application, a moving tag, or the latest N builds. You can see every tester&#39;s effective access at any moment — including what they have lost, and when anything expires.</li><li><strong>Watch the device fleet</strong> — the devices your testers install from: identifiers, models, OS versions, owners. You can correct metadata, deactivate a device, and export the provisioning list (the export is audited).</li><li><strong>Read your tenant&#39;s picture</strong> — the applications your tenant can see (owned plus shared), their working-set versions, effective testers, and the releases currently targeting you. The tenant dashboard is your landing view; tenant analytics feed it.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and open your tenant dashboard.</strong> From the tenants listing, your tenant&#39;s row opens the member roster, the device fleet, and the dashboard — the counts, the catalog your testers can choose from, and the releases currently targeting your tenant:</p><p><img src="'+o+'" alt="The tenant dashboard"></p></li><li><p><strong>Meet your members.</strong> The member roster shows roles and membership status. Add the colleagues who work this tenant with you; suspend instead of removing when someone is only rotating out — their history stays.</p></li><li><p><strong>Link your first tester.</strong> A tester record (created on the <a href="/shipperdog/snapshot/roles/qa-engineer">QA Engineer</a> or Organization Admin track) becomes a portal user for your tenant the moment you link it. The tester accepts their email invitation, sets a password, and signs in to the portal — the flow is the <a href="/shipperdog/snapshot/roles/tester">Tester quickstart</a> your testers will walk.</p></li><li><p><strong>Grant access to a build.</strong> Decide what the tester may install: the whole application, one exact version, a tag like <code>BETA</code>, or the newest N builds. The effective-access view shows the result live — including each grant&#39;s expiry, and nothing is ever silently swept: revoked or expired grants stay visible as history.</p></li><li><p><strong>Check the device fleet.</strong> Once installs happen, devices register: the fleet listing with its per-device facts is <a href="/shipperdog/snapshot/how-to/console/devices">devices</a> — and the CSV export (your provisioning list) is one audited click.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a> — what your scope guarantees and where it ends</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> for the four grant shapes and the effective-access rules you administer</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback analytics</a> for the tenant metrics on your dashboard</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/devices">devices</a>, <a href="/shipperdog/snapshot/how-to/console/tenants">tenants</a></li><li>[ ] Send your testers the <a href="/shipperdog/snapshot/roles/tester">Tester quickstart</a></li></ul>',11)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
